#!/usr/bin/env python3
"""One-time strip of .tex line numbers from the test corpus's messages and comments.

Every citation PATH.tex:N[-M] (with continuations ", :N-M", " with :N", " and :N")
in a test file is resolved against today's Specification/ tree and replaced by the
name of the heading (chapter/section/subsection/paragraph) the cited lines sit under,
plus the \\Method/\\Function entry's name where the lines sit inside one.

Usage: strip.py survey | apply
"""
import os, re, subprocess, sys, json, collections

ROOT = subprocess.check_output(['git', 'rev-parse', '--show-toplevel'], text=True).strip()
SPEC = os.path.join(ROOT, 'Specification')
TEST_DIRS = ['ProjectFortress/tests', 'ProjectFortress/compiler_tests', 'ProjectFortress/library_tests']

CITE = re.compile(
    r'(?P<path>(?:[A-Za-z0-9_-]+/)*[A-Za-z0-9_-]+\.tex):(?P<first>\d+(?:-\d+)?)'
    r'(?P<cont>(?:(?:,[ ]?|[ ]with[ ]|[ ]and[ ]):\d+(?:-\d+)?)*)')
CONT = re.compile(r'(?P<sep>,[ ]?|[ ]with[ ]|[ ]and[ ]):(?P<spec>\d+(?:-\d+)?)')
HEAD = re.compile(r'^\s*\\(chapter|section|subsection|subsubsection|paragraph)\*?\{')
ENTRY = re.compile(r'^\s*\\(Method|Function|Trait|Object|Variable)\{')

# ---------------------------------------------------------------- spec files
SPEC_FILES = []
for d, _, fs in os.walk(SPEC):
    for f in fs:
        if f.endswith('.tex'):
            SPEC_FILES.append(os.path.relpath(os.path.join(d, f), ROOT))

def resolve(path):
    if path.startswith('Specification/'):
        return [path] if path in SPEC_FILES else []
    return [p for p in SPEC_FILES if p.endswith('/' + path)]

_cache = {}
def lines_of(p):
    if p not in _cache:
        with open(os.path.join(ROOT, p), encoding='utf-8') as fh:
            _cache[p] = fh.read().split('\n')
    return _cache[p]

# ---------------------------------------------------------------- TeX -> text
def brace_arg(s, i):
    """s[i] == '{'; return (content, index after closing brace)."""
    assert s[i] == '{'
    depth, j = 0, i
    while j < len(s):
        c = s[j]
        if c == '\\':
            j += 2; continue
        if c == '{': depth += 1
        elif c == '}':
            depth -= 1
            if depth == 0:
                return s[i + 1:j], j + 1
        j += 1
    raise ValueError('unbalanced: ' + s)

MACRO_TEXT = {  # macros whose argument is kept as text
    'KWD', 'TYP', 'VAR', 'OPR', 'EXP', 'emph', 'textit', 'textbf', 'texttt', 'tt', 'mathrm',
    'mbox', 'hbox', 'STR', 'CONST', 'ID', 'txt', 'text', 'FLD', 'TYPE', 'EXPR', 'VAL',
}
MACRO_SYM = {'mathbb{Z}': 'ZZ', 'mathbb{N}': 'NN', 'mathbb{R}': 'RR', 'mathbb{Q}': 'QQ',
             'ldots': '...', 'cdots': '...', '&': '&', '_': '_', '%': '%', '#': '#', '$': '$'}

def detex(s):
    out, i = [], 0
    while i < len(s):
        c = s[i]
        if c == '\\':
            m = re.match(r'\\([A-Za-z]+)\*?\s*', s[i:])
            if not m:
                out.append(s[i + 1]); i += 2; continue
            name = m.group(1); j = i + m.end()
            if name == 'mathbb' and j < len(s) and s[j] == '{':
                arg, j2 = brace_arg(s, j)
                out.append({'Z': 'ZZ', 'N': 'NN', 'R': 'RR', 'Q': 'QQ'}.get(arg, arg)); i = j2; continue
            if name in ('ldots', 'cdots', 'dots'):
                out.append('...'); i = j; continue
            if name in ('label', 'index', 'footnote', 'cite', 'ref'):
                if j < len(s) and s[j] == '{':
                    _, j = brace_arg(s, j)
                i = j; continue
            if j < len(s) and s[j] == '{':
                arg, j2 = brace_arg(s, j)
                out.append(detex(arg)); i = j2; continue
            # unknown bare macro: drop it, keep going
            out.append('\\' + name); i = j; continue
        if c in '{}$':
            i += 1; continue
        if c == '~':
            out.append(' '); i += 1; continue
        out.append(c); i += 1
    t = ''.join(out)
    t = t.replace('``', '"').replace("''", '"').replace('--', '-')
    return re.sub(r'\s+', ' ', t).strip()

# ---------------------------------------------------------------- structure
def headings(p):
    """list of (line_no 1-based, kind, text)"""
    L, res = lines_of(p), []
    for i, ln in enumerate(L):
        m = HEAD.match(ln)
        if m:
            k = ln.index('{', m.start())
            # heading may span lines
            s = '\n'.join(L[i:i + 5])
            k = s.index('{', m.start())
            arg, _ = brace_arg(s, k)
            res.append((i + 1, m.group(1), detex(arg)))
    return res

def entries(p):
    """\\Method-like entries: (line_no of first signature comment or macro, macro line, names)"""
    L, res = lines_of(p), []
    for i, ln in enumerate(L):
        m = ENTRY.match(ln)
        if not m:
            continue
        sigs, j = [], i - 1
        while j >= 0 and re.match(r'^%+\s*\S', L[j]):
            sigs.insert(0, re.sub(r'^%+\s*', '', L[j]).strip()); j -= 1
        res.append((j + 2, i + 1, m.group(1), sigs, ln.strip()))
    return res

def entry_name(sigs, macro_line):
    """Short name of an entry from its ASCII signature comments."""
    names = []
    for s in sigs:
        m = re.match(r'^(opr\s+)?(.*?)\s*(\(|:|$)', s)
        # opr NAME(self...) / opr (self)! / opr |self| / NAME(self...)
        if s.startswith('opr '):
            rest = s[4:].strip()
            m2 = re.match(r'^([^\s(]+)\s*\(', rest)
            if m2:
                names.append('opr ' + m2.group(1))
            else:
                names.append('opr ' + re.sub(r'\s*:\s*[^:]*$', '', rest))
        else:
            m2 = re.match(r'^([A-Za-z_][A-Za-z0-9_]*)', s)
            if m2:
                names.append(m2.group(1))
    return names

def locate(p, a, b):
    """innermost heading at line a, headings inside (a, b], enclosing entry at a."""
    hs = headings(p)
    at = [h for h in hs if h[0] <= a]
    inside = [h for h in hs if a < h[0] <= b]
    head = at[-1] if at else None
    ent = None
    for e in entries(p):
        if e[0] <= a and (head is None or e[0] > head[0]):
            ent = e
    # an entry ends where the next entry or heading starts
    if ent is not None:
        nxt = [e[0] for e in entries(p) if e[0] > ent[0]] + [h[0] for h in hs if h[0] > ent[0]]
        if nxt and min(nxt) <= a:
            ent = None
    return head, inside, ent

def parse_spec(s):
    if '-' in s:
        a, b = s.split('-'); return int(a), int(b)
    return int(s), int(s)

# ---------------------------------------------------------------- scan
def test_files():
    out = subprocess.check_output(['git', 'ls-files', '--'] + TEST_DIRS, cwd=ROOT, text=True).split('\n')
    return [f for f in out if f.endswith(('.fss', '.fsi', '.test'))]

def scan():
    cites = []
    for f in test_files():
        with open(os.path.join(ROOT, f), encoding='utf-8') as fh:
            L = fh.read().split('\n')
        for i, ln in enumerate(L):
            for m in CITE.finditer(ln):
                specs = [m.group('first')] + [c.group('spec') for c in CONT.finditer(m.group('cont'))]
                cites.append(dict(file=f, line=i + 1, text=ln, start=m.start(), end=m.end(),
                                  match=m.group(0), path=m.group('path'), specs=specs))
    return cites

if __name__ == '__main__':
    cites = scan()
    print(len(cites), 'citation groups,', sum(len(c['specs']) for c in cites), 'line specs,',
          len({c['file'] for c in cites}), 'files')

