# ---------------------------------------------------------------- structure
HEAD_RE = re.compile(r'^\s*\\(chapter|section|subsection|subsubsection|paragraph)\*?\{')
LIBSEC_RE = re.compile(r'^\s*\\(Trait|Object)\{')
LIBSUB_RE = re.compile(r'^\s*\\(Method|Function|Variable)(\*?)\{')
INPUT_RE = re.compile(r'\\input\{\\home/([^}]+)\}')
SYMS = {'COLON': ':', 'ASSIGN': ':=', 'COLONOP': ':'}

def detex2(s):
    for k, v in SYMS.items():
        s = re.sub(r'\\' + k + r'(?![A-Za-z])(\{\})?', v, s)
    return detex(s)

_struct = {}
def structure(p):
    """list of dicts: line, kind, text (headings), or entry groups (kind 'entry')."""
    if p in _struct:
        return _struct[p]
    L, res = lines_of(p), []
    i = 0
    while i < len(L):
        ln = L[i]
        m = HEAD_RE.match(ln)
        if m:
            s = '\n'.join(L[i:i + 5]); k = s.index('{', m.start())
            arg, _ = brace_arg(s, k)
            text = detex(arg)
            if m.group(1) == 'paragraph':
                text = text.rstrip(':').strip()
            # scope end of a run-in paragraph: first run of >= 2 blank lines
            item = dict(line=i + 1, kind=m.group(1), text=text, raw=ln.strip())
            if m.group(1) == 'paragraph':
                j = i + 1
                while j + 1 < len(L) and not (L[j].strip() == '' and L[j + 1].strip() == ''):
                    j += 1
                item['until'] = j  # last line (1-based) still inside
            res.append(item); i += 1; continue
        m = LIBSEC_RE.match(ln)
        if m:
            k = ln.index('{', m.start()); arg, _ = brace_arg(ln, k)
            res.append(dict(line=i + 1, kind=m.group(1).lower(), text=detex(arg), raw=ln.strip()))
            i += 1; continue
        m = LIBSUB_RE.match(ln)
        if m:
            # a group: this macro line and the following \Method* lines
            first = i
            j = i + 1
            while j < len(L) and LIBSUB_RE.match(L[j]) and LIBSUB_RE.match(L[j]).group(2) == '*':
                j += 1
            sigs, c = [], first - 1
            while c >= 0 and re.match(r'^%+\s*\S', L[c]) and not re.match(r'^%+\s*(end|%)', L[c]):
                sigs.insert(0, re.sub(r'^%+\s*', '', L[c]).strip()); c -= 1
            macros = []
            for t in range(first, j):
                mm = LIBSUB_RE.match(L[t]); k = L[t].index('{', mm.start())
                arg, _ = brace_arg(L[t], k); macros.append(detex2(arg))
            res.append(dict(line=c + 2, kind='entry', macro=m.group(1), sigs=sigs, macros=macros,
                            first=first + 1, last=j, raw=L[first].strip()))
            i = j; continue
        i += 1
    _struct[p] = res
    return res

def sig_name(s):
    """'opr CHOOSE(self, other: ZZ): ZZ' -> ('opr', 'CHOOSE', nparams); 'floor(self): ZZ' -> ('', 'floor', 1)"""
    s = s.strip()
    if s.startswith('getter ') or s.startswith('setter '):
        s = s.split(' ', 1)[1]
    if s.startswith('opr '):
        rest = s[4:].strip()
        m = re.match(r'^([^\s(]+)\s*\((.*?)\)', rest)
        if m:
            return ('opr', m.group(1), len([x for x in m.group(2).split(',') if x.strip()]))
        rest = re.sub(r'\s*:\s*[^:]*$', '', rest).strip()
        return ('opr', rest, 1)
    m = re.match(r'^([A-Za-z_][A-Za-z0-9_]*)\s*\((.*?)\)', s)
    if m:
        return ('', m.group(1), len([x for x in m.group(2).split(',') if x.strip()]))
    m = re.match(r'^([A-Za-z_][A-Za-z0-9_]*)', s)
    return ('', m.group(1), 0) if m else None

def and_join(xs):
    xs = list(xs)
    return xs[0] if len(xs) == 1 else ', '.join(xs[:-1]) + ' and ' + xs[-1]

def entry_render(p, e):
    sigs = e['sigs'] or e['macros']
    parts = [sig_name(s) for s in sigs]
    parts = [x for x in parts if x and '\\' not in x[1] and ' ' not in x[1]]
    oprs = [x[1] for x in parts if x[0] == 'opr']
    meths = [x[1] for x in parts if x[0] == '']
    # unary / binary qualifier when another entry of this file has the same names
    key = (tuple(oprs), tuple(meths))
    same = [f for f in structure(p) if f['kind'] == 'entry' and f is not e and
            (lambda q: (tuple(y[1] for y in q if y[0] == 'opr'), tuple(y[1] for y in q if y[0] == '')))(
                [sig_name(s) for s in (f['sigs'] or f['macros']) if sig_name(s)]) == key]
    out = []
    if oprs:
        q = ''
        if same and parts:
            n = parts[0][2]
            q = {1: 'unary ', 2: 'binary '}.get(n, '')
        out.append(q + 'opr ' + and_join(dict.fromkeys(oprs)))
    if meths:
        names = list(dict.fromkeys(meths))
        word = {'Method': 'method', 'Function': 'function', 'Variable': 'variable'}[e['macro']]
        out.append(word + ('s ' if len(names) > 1 else ' ') + and_join(names))
    return ', '.join(out) if out else None

def includer(p):
    rel = p[len('Specification/'):-len('.tex')]
    for q in SPEC_FILES:
        for i, ln in enumerate(lines_of(q)):
            m = INPUT_RE.search(ln)
            if m and m.group(1).replace('.tex', '') == rel:
                return q, i + 1
    return None

def heading_at(p, a):
    """innermost live heading (not entry) at line a, following \\input to the parent when none."""
