def blame_check(rows):
    """For every citation: the spec text at the commit that last wrote the test line, at the cited
    lines, against today's text at the same lines. Unequal -> find where the old text is today."""
    import functools
    @functools.lru_cache(None)
    def blame(f):
        out = subprocess.check_output(['git', 'blame', '--porcelain', '--', f], cwd=ROOT, text=True)
        res, cur = {}, None
        for ln in out.split('\n'):
            m = re.match(r'^([0-9a-f]{40}) \d+ (\d+)', ln)
            if m:
                cur = m.group(1); res[int(m.group(2))] = cur
        return res
    @functools.lru_cache(None)
    def spec_at(commit, p):
        try:
            return subprocess.check_output(['git', 'show', '%s:%s' % (commit, p)], cwd=ROOT, text=True,
                                           stderr=subprocess.DEVNULL).split('\n')
        except subprocess.CalledProcessError:
            return None
    report = []
    for r in rows:
        c = r['c']; commit = blame(c['file'])[c['line']]
        old = spec_at(commit, r['spec']); now = lines_of(r['spec'])
        for raw in c['specs']:
            a, b = parse_spec(raw)
            if old is None:
                report.append((r, raw, commit, 'spec file absent at the commit')); continue
            if old[a - 1:b] == now[a - 1:b]:
                continue
            blk = old[a - 1:b]
            hits = [i + 1 for i in range(len(now) - len(blk) + 1) if now[i:i + len(blk)] == blk]
            report.append((r, raw, commit, 'moved: today at %s' % hits))
    return report
